package glitch

import data.glitch_lib

# Weak cryptographic algorithms
weak_symmetric_algorithms := {"DES", "3DES", "RC2", "RC4", "Blowfish"}
weak_hash_functions := {"MD5", "SHA1", "SHA-0", "RIPEMD"}
weak_block_modes := {"ECB"}
weak_tls_versions := {"1.0", "TLSv1", "TLSv1.0", "TLSv1.1", "TLS1", "TLS1.1", "SSLv2", "SSLv3", "SSLv3", "SSLv2"}

# Weak cipher suites and protocols
weak_ciphers := {"NULL", "EXPORT", "ANON", "RC4-SHA", "DES-CBC"}
weak_policies := {"TLS-1-0", "TLS-1-1", "SSLv3", "SSLv2"}

# Encryption-related attribute names
encryption_attr_names := {
    "encryption_algorithm", "sse_algorithm", "bucket_encryption",
    "algorithm", "cipher", "cipher_suite", "ciphers",
    "ssl_policy", "tls_policy", "security_policy",
    "protocol_version", "minimum_tls_version", "tls_version",
    "vpn_encryption", "ipsec_policy", "transit_encryption",
    "secret_encryption", "password_encryption", "token_encryption"
}

# Key size attribute names
key_size_attrs := {"key_size", "key_length", "key_bits", "keylen", "key_bit_length"}

# Encryption enablement attribute names
encryption_enable_attrs := {
    "encryption_at_rest", "in_transit_encryption", "storage_encrypted",
    "enforce_https", "ssl_only", "block_public_policy"
}

# Check if string contains weak algorithm
contains_weak_algorithm(str) {
    weak_symmetric_algorithms[_] == str
} else {
    weak_hash_functions[_] == str
} else {
    weak_block_modes[_] == str
} else {
    regex.match("(?i).*(DES|3DES|RC2|RC4|Blowfish|MD5|SHA1|SHA-0|RIPEMD|ECB).*", str)
}

# Check if string contains weak TLS version
contains_weak_tls(str) {
    weak_tls_versions[_] == str
} else {
    regex.match("(?i).*(TLS-?1\\.?0|TLS-?1\\.?1|SSLv?2|SSLv?3).*", str)
}

# Check if string contains weak cipher
contains_weak_cipher(str) {
    weak_ciphers[_] == str
} else {
    regex.match("(?i).*(NULL|EXPORT|ANON|RC4-SHA|DES-CBC).*", str)
}

# Check if value represents weak key size
is_weak_key_size(attr_name, value) {
    key_size_attrs[_] == attr_name
    value.ir_type == "Integer"
    value.value < 128
} else {
    key_size_attrs[_] == attr_name
    value.ir_type == "String"
    to_number(value.value) < 128
} else {
    key_size_attrs[_] == attr_name
    value.ir_type == "String"
    regex.match("^[0-9]+$", value.value)
    to_number(value.value) < 128
}

# Extract string value from various expression types
get_string_value(node) = str {
    node.ir_type == "String"
    str := node.value
} else = str {
    node.ir_type == "VariableReference"
    str := node.value
}

# Check if encryption is explicitly disabled
is_encryption_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower(value.value) == "false"
} else {
    value.ir_type == "String"
    lower(value.value) == "disabled"
}

# Main rule: weak encryption algorithm
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    encryption_attr_names[_] == lower(attr.name)

    str_val := get_string_value(attr.value)
    contains_weak_algorithm(str_val)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm detected (DES, 3DES, RC4, MD5, SHA1, ECB mode, etc.). (CWE-326)"
    }
}

# Main rule: weak TLS/SSL version
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    tls_attrs := {"minimum_tls_version", "tls_version", "protocol_version", "ssl_policy", "tls_policy"}
    tls_attrs[_] == lower(attr.name)

    str_val := get_string_value(attr.value)
    contains_weak_tls(str_val)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak TLS/SSL version detected (TLS 1.0, TLS 1.1, SSLv2, SSLv3). (CWE-326)"
    }
}

# Main rule: weak cipher suite
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    cipher_attrs := {"cipher_suite", "ciphers", "cipher_suites"}
    cipher_attrs[_] == lower(attr.name)

    str_val := get_string_value(attr.value)
    contains_weak_cipher(str_val)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cipher suite detected (NULL, EXPORT, ANON, RC4-SHA, DES-CBC). (CWE-326)"
    }
}

# Main rule: weak key size
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    key_size_attrs[_] == lower(attr.name)
    is_weak_key_size(attr.name, attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Key size is too small (less than 128 bits for symmetric encryption). (CWE-326)"
    }
}

# Main rule: encryption explicitly disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

