    encryption_enable_attrs[_] == lower(attr.name)
    is_encryption_disabled(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Encryption is explicitly disabled. (CWE-326)"
    }
