}

# Helper: check if string is weak hash
is_weak_hash(str) {
    lower_str := lower(str)
    lower_str == "md5"
} else {
    lower_str := lower(str)
    lower_str == "sha"
} else {
    lower_str := lower(str)
    lower_str == "sha1"
